package com.trampolim.api.career;
import java.util.*;import java.time.*;import java.net.URI;import static com.trampolim.api.radar.RadarModel.*;
public final class CareerRules {
 private CareerRules(){}
 public static final Set<String> REGIONS=Set.of("AC","AL","AP","AM","BA","CE","DF","ES","GO","MA","MT","MS","MG","PA","PB","PR","PE","PI","RJ","RN","RS","RO","RR","SC","SP","SE","TO");
 public static String region(String value,boolean optional){String v=text(value,2).toUpperCase(Locale.ROOT);if(!(optional&&v.isEmpty())&&!REGIONS.contains(v))bad("Selecione uma unidade federativa brasileira válida.");return v;}
 public static void page(long before,int limit){if(before<1||limit<1||limit>50)bad("Use páginas de até cinquenta registros.");}
 public static String https(String value){String v=text(value,1000);if(v.isEmpty())return v;try{var uri=URI.create(v);if(!"https".equalsIgnoreCase(uri.getScheme())||uri.getHost()==null||uri.getUserInfo()!=null||uri.getFragment()!=null)throw new IllegalArgumentException();return v;}catch(Exception e){bad("Use um endereço HTTPS válido, sem credenciais. O servidor não acessará esse endereço.");return "";}}
 public static void dates(String from,String to){try{LocalDate a=LocalDate.parse(from),b=LocalDate.parse(to);if(b.isBefore(a)||b.isAfter(a.plusYears(1)))bad("Use um período de até um ano.");}catch(org.springframework.web.server.ResponseStatusException e){throw e;}catch(Exception e){bad("Informe datas válidas.");}}
 public static Map<String,Object> band(long count){return count<10?Map.of("available",false,"label","Amostra insuficiente (mínimo 10)"):Map.of("available",true,"label",(count/10*10)+"–"+(count/10*10+9));}
 public static Map<String,Object> pageResult(List<Map<String,Object>> rows,int limit){var p=new LinkedHashMap<String,Object>();p.put("items",rows.stream().limit(limit).toList());p.put("nextCursor",rows.size()>limit?rows.get(limit-1).get("id"):null);return p;}
 public static String redact(String value){String s=Objects.toString(value,"");s=s.replaceAll("(?i)[A-Z0-9._%+-]+@[A-Z0-9.-]+\\.[A-Z]{2,}","[e-mail removido]");s=s.replaceAll("(?<![0-9])(?:\\+?55[ \t.-]?)?(?:\\(?[0-9]{2}\\)?[ \t.-]?)?[0-9]{4,5}[ \t.-]?[0-9]{4}(?![0-9])","[contato/documento removido]");s=s.replaceAll("(?i)(?:sk-[a-z0-9_-]{12,}|AQ\\.[a-z0-9_-]{12,})","[segredo removido]");return s;}
 public static List<Map<String,Object>> localGuidance(String topic,String context){return List.of(Map.of("kind","strength","text",context.isBlank()?"Você está organizando seu próximo passo profissional.":"Há um contexto informado que pode ser revisado com exemplos concretos."),Map.of("kind","improvement","text",switch(topic){case "RESUME"->"Organize objetivo, formação, projetos e experiências reais; não invente vínculos de trabalho.";case "INTERVIEW"->"Descreva situação, sua ação e resultado observado. Evite respostas decoradas e não invente experiências.";case "JOB"->"Separe requisitos obrigatórios e desejáveis. Use o Radar para conferir competências e lacunas.";case "TRAINING"->"Consulte cursos publicados do Capacita e escolha o conteúdo relacionado à lacuna, sem repetir habilidades já comprovadas.";case "SKILLS"->"Diferencie habilidade declarada de habilidade comprovada por avaliação ou evidência autorizada.";default->"Defina uma ocupação, identifique competências necessárias e escolha um próximo passo verificável.";}),Map.of("kind","nextStep","text","Registre uma ação concreta e peça revisão humana quando precisar. Esta orientação não garante contratação."));}
}
